"""Configure persistent ThinLTO storage without changing the selected LTO mode."""import argparsefrom pathlib import Pathimport redef configure(text, directory):    if any(c.isspace() for c in directory):        raise ValueError('ThinLTO cache path must not contain whitespace')    flag = '--thinlto-cache-dir=' + directory    if flag in text:        return text    existing = r'--thinlto-cache-dir=(?:\$\(extmod-prefix\))?\.thinlto-cache'    if re.search(existing, text):        return re.sub(existing, lambda match: flag, text)    if '--thinlto-cache-dir=' in text:        return text    anchor = 'ifdef CONFIG_LTO_CLANG_THIN\n'    if anchor in text:        return text.replace(anchor, anchor + 'KBUILD_LDFLAGS += ' + flag + '\n', 1)    return textdef main():    parser = argparse.ArgumentParser(description=__doc__)    parser.add_argument('makefile', type=Path)    parser.add_argument('directory')    args = parser.parse_args()    text = args.makefile.read_text()    updated = configure(text, args.directory)    if updated != text:        args.makefile.write_text(updated)        print('ThinLTO 链接缓存已接入持久化目录。')    else:        print('ThinLTO 参数已配置或源码入口未识别，保留现有链接行为。')if __name__ == '__main__':    main()